-- Verticales adicionales (3ª ampliación, ~10 por industria). Sincronizado con lib/leaf-catalog.ts (VERTICAL_ROWS).
-- Idempotente: INSERT industries_catalog + industry_verticals ON CONFLICT DO UPDATE.

ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  sort_order = EXCLUDED.sort_order,
  parent_slug = EXCLUDED.parent_slug;

SELECT c.slug, c.parent_slug, c.name, COALESCE(c.sort_order, 0) + 100, i.maps_to
FROM public.industries_catalog c
INNER JOIN public.industries i ON i.slug = c.parent_slug
WHERE c.slug IN (
  'capital-riesgo-venture-debt', 'embedded-finance-b2b', 'fx-hedging-global', 'planeacion-patrimonial-sucesoria', 'consolidacion-reporting-ifrs',
  'activos-improductivos-npl', 'custodia-valores-post-trade', 'seguros-corporativos-pyme', 'core-banking-tech-proveedores', 'spinouts-corporate-venturing',
  'atencion-primaria-comunitaria', 'urgencias-hospitalarias', 'medicina-deportiva-rehabilitacion', 'genomica-terapias-avanzadas', 'enfermeria-domiciliaria-paliativos',
  'salud-materno-infantil-vertical', 'optometria-salud-visual', 'patologia-clinica-especializada', 'logistica-suministro-hospitalario', 'telefarmacia-cadena-frio',
  'preescolar-primera-infancia-edu', 'stem-robotica-maker', 'coaching-certificaciones-profesionales', 'universidad-corporativa-academy', 'editorial-educativa-contenidos',
  'becas-financiamiento-estudiantil', 'internacionalizacion-educativa', 'evaluacion-online-proctoring', 'desarrollo-docente-continua', 'operaciones-campus-servicios',
