  'erp-crm-implementacion', 'multicloud-finops', 'low-code-bpm-orquestacion', 'automatizacion-rpa', 'semiconductor-fabless-ip',
  'privacidad-datos-sector-publico', 'catastro-catastral-registro', 'archivos-nacionales-documentacion', 'identidad-digital-ciudadania', 'cultura-artes-politica-publica',
  'ciencia-tecnologia-politica-innovacion', 'adquisiciones-defensa-industrial', 'transicion-justa-energia-publica', 'estadistica-oficial-encuestas', 'migracion-consular-servicios',
  'centros-comerciales-experiencia', 'retail-automotriz-posventa', 'farmacia-parafarmacia-retail', 'pet-care-retail', 'hogar-muebles-decoracion',
  'deportes-outdoor-retail', 'optica-audio-retail', 'b2b-marketplace-mayoreo-digital', 'loss-prevention-seguridad-retail', 'libreria-papeleria-cultura-retail',
  'standup-comedy-clubes', 'venues-conciertos-en-vivo', 'management-artistico-booking', 'sync-licencias-musica-publicidad', 'vfx-post-animation-studios',
